  if(mode==='SERVIS'||mode==='SERVIS_EDIT')await api(`/modules/trafik-kazalari/${selectedId}/servis${mode==='SERVIS_EDIT'?`/${form.kaza_servis_id}`:''}`,{method:mode==='SERVIS_EDIT'?'PUT':'POST',body:JSON.stringify(form)});
  if(mode==='FATURA'||mode==='FATURA_EDIT')await api(`/modules/trafik-kazalari/${selectedId}/fatura${mode==='FATURA_EDIT'?`/${form.kaza_fatura_id}`:''}`,{method:mode==='FATURA_EDIT'?'PUT':'POST',body:JSON.stringify({...form,toplam_tutar:Number(form.toplam_tutar||0)})});
